import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Account Deletion","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/help/account-deletion.md","filePath":"v1/en/help/account-deletion.md"}'),n={name:"v1/en/help/account-deletion.md"};function l(c,e,r,d,s,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="account-deletion" tabindex="-1">Account Deletion <a class="header-anchor" href="#account-deletion" aria-label="Permalink to &quot;Account Deletion&quot;">​</a></h1><p>Deleting your account will clear all data for this account in both the cloud and on this device. Please make sure you understand the impact before proceeding.</p><h2 id="what-will-happen" tabindex="-1">What will happen <a class="header-anchor" href="#what-will-happen" aria-label="Permalink to &quot;What will happen&quot;">​</a></h2><ul><li>Cloud data: all cloud-synced data for this account will be removed (including but not limited to ledgers, bills, categories, tags, etc.).</li><li>Local data: all local data for this account on the current device will be removed (including offline data).</li><li>Irreversible: once completed, deleted data cannot be recovered.</li></ul><h2 id="will-my-subscription-be-affected" tabindex="-1">Will my subscription be affected <a class="header-anchor" href="#will-my-subscription-be-affected" aria-label="Permalink to &quot;Will my subscription be affected&quot;">​</a></h2><p>Account deletion does not affect your active subscription period.</p><p>If you are a paid subscriber, after deleting the account you can sign in again and tap “Restore Purchases” in the app to restore your membership status (subject to the App Store / Google Play subscription status).</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><ul><li>If you need to keep your data, export/backup in the app first (if available).</li><li>After deletion, signing in again is treated as a fresh environment and you may need to re-sync/re-import your data.</li></ul>',9)])])}const m=a(n,[["render",l]]);export{h as __pageData,m as default};
